/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:      #0d0d0f;
  --bg-surface:   #141417;
  --bg-card:      #1a1a1f;
  --bg-hover:     #22222a;
  --border:       #2a2a35;
  --accent:       #e8b86d;
  --accent-dim:   #c4954a;
  --accent-glow:  rgba(232,184,109,.18);
  --red:          #e85d5d;
  --text-primary: #f0eee8;
  --text-secondary:#9d9b94;
  --text-muted:   #5c5b56;
  --radius-sm:    6px;
  --radius-md:    12px;
  --radius-lg:    20px;
  --transition:   .22s ease;
  --font-sans:    'Inter', system-ui, -apple-system, sans-serif;
  --font-serif:   'Playfair Display', Georgia, serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; }
button { cursor: pointer; font-family: inherit; }

/* ===== TYPOGRAPHY ===== */
.section-label {
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
}

.section-header-text { display: flex; flex-direction: column; gap: .4rem; }

.view-all {
  font-size: .82rem;
  font-weight: 500;
  color: var(--accent);
  border-bottom: 1px solid var(--accent-dim);
  padding-bottom: 2px;
  white-space: nowrap;
  transition: color var(--transition), border-color var(--transition);
}
.view-all:hover { color: var(--text-primary); border-color: var(--text-secondary); }

/* ===== LAYOUT ===== */
.container { max-width: 1280px; margin: 0 auto; padding: 0 clamp(1rem, 4vw, 2.5rem); }
section { padding: 5rem 0; }
section + section { border-top: 1px solid var(--border); }

/* ===== NAVBAR ===== */
.navbar {
  position: sticky; top: 0; z-index: 100;
  background: rgba(13,13,15,.85);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border);
}

.navbar-inner {
  display: flex; align-items: center; gap: 1.5rem;
  height: 64px;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--text-primary);
  flex-shrink: 0;
}
.nav-logo span { color: var(--accent); }

.nav-links {
  display: flex; gap: .25rem; align-items: center;
  list-style: none; margin-left: 1.5rem;
}

.nav-links a {
  font-size: .85rem; font-weight: 500;
  color: var(--text-secondary);
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover { color: var(--text-primary); background: var(--bg-hover); }
.nav-links a.active { color: var(--text-primary); }

.nav-spacer { flex: 1; }

.nav-search {
  display: flex; align-items: center; gap: .6rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: .45rem 1rem;
  transition: border-color var(--transition);
}
.nav-search:focus-within { border-color: var(--accent-dim); }
.nav-search input {
  background: none; border: none; outline: none;
  color: var(--text-primary); font-size: .85rem;
  width: 180px;
}
.nav-search input::placeholder { color: var(--text-muted); }
.nav-search svg { flex-shrink: 0; color: var(--text-muted); }

.nav-actions { display: flex; gap: .5rem; align-items: center; }

.nav-btn {
  position: relative;
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  background: none; border: none;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.nav-btn:hover { color: var(--text-primary); background: var(--bg-hover); }

.badge {
  position: absolute; top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--accent); color: #000;
  font-size: .6rem; font-weight: 700;
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
}

.hamburger { display: none; }

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: min(90vh, 720px);
  display: flex; align-items: center;
  overflow: hidden;
  padding: 0;
  border-bottom: none;
}

.hero-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(232,184,109,.07) 0%, transparent 65%),
    radial-gradient(ellipse 50% 80% at 10% 80%, rgba(100,80,200,.06) 0%, transparent 60%),
    linear-gradient(160deg, #0f0f14 0%, #0d0d0f 100%);
}

.hero-grid-overlay {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: .25;
  mask-image: radial-gradient(ellipse 70% 70% at 60% 50%, black 30%, transparent 75%);
}

.hero-content {
  position: relative; z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  padding: 5rem 0;
}

.hero-eyebrow {
  display: inline-flex; align-items: center; gap: .5rem;
  background: var(--accent-glow);
  border: 1px solid rgba(232,184,109,.25);
  border-radius: 999px;
  padding: .3rem .9rem;
  font-size: .72rem; font-weight: 600; letter-spacing: .1em;
  text-transform: uppercase; color: var(--accent);
  margin-bottom: 1.4rem;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.02em;
  margin-bottom: 1.2rem;
}

.hero-title .highlight {
  background: linear-gradient(135deg, var(--accent) 0%, #f0d080 60%, var(--accent-dim) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-desc {
  font-size: 1.05rem;
  color: var(--text-secondary);
  max-width: 42ch;
  margin-bottom: 2.2rem;
  line-height: 1.75;
}

.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; align-items: center; }

.btn-primary {
  display: inline-flex; align-items: center; gap: .55rem;
  background: var(--accent);
  color: #0d0d0f;
  font-size: .9rem; font-weight: 700;
  padding: .8rem 1.8rem;
  border: none; border-radius: 999px;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 4px 20px var(--accent-glow);
}
.btn-primary:hover { background: #f0c87a; transform: translateY(-2px); box-shadow: 0 8px 28px rgba(232,184,109,.3); }

.btn-ghost {
  display: inline-flex; align-items: center; gap: .55rem;
  background: none;
  color: var(--text-secondary);
  font-size: .9rem; font-weight: 500;
  padding: .8rem 1.4rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.btn-ghost:hover { color: var(--text-primary); border-color: var(--text-secondary); background: var(--bg-hover); }

.hero-stats {
  display: flex; gap: 2.5rem; margin-top: 3rem;
}

.hero-stat-num {
  font-size: 1.5rem; font-weight: 800;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}
.hero-stat-label { font-size: .78rem; color: var(--text-muted); margin-top: .1rem; }

.hero-visual {
  position: relative;
  display: flex; justify-content: center; align-items: center;
}

.hero-product-card {
  position: relative;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  width: 340px;
  box-shadow: 0 24px 80px rgba(0,0,0,.5);
}

.hero-product-card::before {
  content: '';
  position: absolute; inset: -1px;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, rgba(232,184,109,.2), transparent 60%);
  z-index: -1;
}

.hero-img-wrap {
  border-radius: var(--radius-md);
  overflow: hidden;
  aspect-ratio: 1 / 1;
  background: linear-gradient(135deg, #1e1e26 0%, #16161d 100%);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 1.4rem;
  font-size: 6rem;
}

.hero-product-tag {
  position: absolute; top: 1.2rem; right: 1.2rem;
  background: var(--red);
  color: #fff;
  font-size: .7rem; font-weight: 700;
  padding: .25rem .65rem; border-radius: 999px;
  letter-spacing: .06em; text-transform: uppercase;
}

.hero-product-name {
  font-weight: 600; font-size: 1rem; margin-bottom: .25rem;
}
.hero-product-brand { font-size: .8rem; color: var(--text-muted); margin-bottom: .75rem; }

.hero-product-footer {
  display: flex; align-items: center; justify-content: space-between;
}
.hero-product-price { font-size: 1.2rem; font-weight: 700; color: var(--accent); }
.hero-product-old { font-size: .82rem; color: var(--text-muted); text-decoration: line-through; margin-left: .4rem; }

.hero-add-btn {
  display: flex; align-items: center; gap: .4rem;
  background: var(--accent); color: #0d0d0f;
  font-size: .8rem; font-weight: 700;
  padding: .55rem 1rem; border: none; border-radius: 999px;
  transition: background var(--transition);
}
.hero-add-btn:hover { background: #f0c87a; }

.floating-badge {
  position: absolute;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: .75rem 1rem;
  display: flex; align-items: center; gap: .6rem;
  box-shadow: 0 8px 32px rgba(0,0,0,.4);
  font-size: .8rem;
}

.floating-badge.badge-rating { top: -16px; left: -40px; }
.floating-badge.badge-shipping { bottom: -16px; right: -40px; }

.fb-icon { font-size: 1.2rem; }
.fb-text strong { display: block; font-size: .82rem; color: var(--text-primary); }
.fb-text span { font-size: .72rem; color: var(--text-muted); }

/* ===== CATEGORIES ===== */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}

.category-card {
  display: flex; flex-direction: column; align-items: center; gap: .65rem;
  padding: 1.4rem .75rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  text-align: center;
}

.category-card:hover {
  border-color: var(--accent-dim);
  background: var(--bg-hover);
  transform: translateY(-3px);
}

.category-icon { font-size: 2rem; }
.category-name { font-size: .8rem; font-weight: 600; color: var(--text-secondary); }
.category-count { font-size: .7rem; color: var(--text-muted); }

/* ===== PRODUCT CARDS ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
}
.product-card:hover {
  border-color: rgba(232,184,109,.3);
  transform: translateY(-4px);
  box-shadow: 0 16px 48px rgba(0,0,0,.4);
}

.product-img-wrap {
  position: relative;
  aspect-ratio: 1 / 1;
  background: linear-gradient(135deg, #1c1c24 0%, #141419 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 4.5rem;
  overflow: hidden;
}

.product-actions {
  position: absolute; top: .75rem; right: .75rem;
  display: flex; flex-direction: column; gap: .4rem;
  opacity: 0; transform: translateX(8px);
  transition: opacity var(--transition), transform var(--transition);
}
.product-card:hover .product-actions { opacity: 1; transform: none; }

.product-action-btn {
  width: 34px; height: 34px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-secondary);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.product-action-btn:hover { color: var(--accent); border-color: var(--accent-dim); background: var(--bg-hover); }
.product-action-btn.wishlisted { color: var(--red); border-color: var(--red); }

.product-tag {
  position: absolute; top: .75rem; left: .75rem;
  font-size: .65rem; font-weight: 700; letter-spacing: .07em; text-transform: uppercase;
  padding: .25rem .6rem; border-radius: 999px;
}
.tag-sale { background: rgba(232,93,93,.15); color: var(--red); border: 1px solid rgba(232,93,93,.3); }
.tag-new  { background: rgba(93,183,232,.12); color: #5db7e8; border: 1px solid rgba(93,183,232,.25); }
.tag-hot  { background: rgba(232,184,109,.12); color: var(--accent); border: 1px solid rgba(232,184,109,.25); }

.product-info { padding: 1rem 1.1rem 1.2rem; }
.product-brand { font-size: .72rem; color: var(--text-muted); margin-bottom: .25rem; letter-spacing: .05em; text-transform: uppercase; }
.product-name { font-size: .92rem; font-weight: 600; margin-bottom: .4rem; line-height: 1.4; }

.product-rating {
  display: flex; align-items: center; gap: .35rem;
  margin-bottom: .7rem;
}
.stars { color: var(--accent); font-size: .75rem; letter-spacing: 1px; }
.rating-count { font-size: .72rem; color: var(--text-muted); }

.product-footer {
  display: flex; align-items: center; justify-content: space-between;
}

.price-group { display: flex; align-items: baseline; gap: .4rem; }
.price { font-size: 1.05rem; font-weight: 700; color: var(--text-primary); }
.price-old { font-size: .8rem; color: var(--text-muted); text-decoration: line-through; }
.price-save { font-size: .72rem; color: var(--red); font-weight: 600; }

.add-to-cart {
  width: 34px; height: 34px;
  background: var(--accent);
  color: #0d0d0f;
  border: none; border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}
.add-to-cart:hover { background: #f0c87a; transform: scale(1.08); }
.add-to-cart.added { background: #5db7e8; }

/* ===== DEALS BANNER ===== */
.deals-section { background: var(--bg-surface); }

.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 1.25rem;
}

.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition);
}
.deal-card:hover { transform: translateY(-4px); box-shadow: 0 20px 56px rgba(0,0,0,.5); }

.deal-card-inner {
  padding: 2rem;
  height: 100%;
  min-height: 240px;
  display: flex; flex-direction: column; justify-content: flex-end;
  position: relative; z-index: 2;
}

.deal-card-bg {
  position: absolute; inset: 0; z-index: 0;
}

.deal-card.deal-primary .deal-card-bg {
  background: linear-gradient(135deg, #1a1020 0%, #0e0e18 60%),
    radial-gradient(ellipse 80% 60% at 80% 20%, rgba(150,80,220,.25) 0%, transparent 60%);
}
.deal-card.deal-gold .deal-card-bg {
  background: linear-gradient(135deg, #1a1508 0%, #0f0e0a 60%),
    radial-gradient(ellipse 80% 60% at 20% 20%, rgba(232,184,109,.2) 0%, transparent 60%);
}
.deal-card.deal-blue .deal-card-bg {
  background: linear-gradient(135deg, #08121a 0%, #0d0f12 60%),
    radial-gradient(ellipse 80% 60% at 80% 80%, rgba(80,140,220,.2) 0%, transparent 60%);
}

.deal-emoji {
  position: absolute; right: 1.5rem; top: 1.5rem;
  font-size: 4rem; z-index: 1; opacity: .6;
}

.deal-badge {
  display: inline-flex; align-items: center;
  background: rgba(232,93,93,.15);
  border: 1px solid rgba(232,93,93,.3);
  color: var(--red);
  font-size: .68rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  padding: .25rem .65rem; border-radius: 999px;
  margin-bottom: .75rem;
  width: fit-content;
}

.deal-card.deal-gold .deal-badge {
  background: rgba(232,184,109,.12);
  border-color: rgba(232,184,109,.25);
  color: var(--accent);
}

.deal-title {
  font-family: var(--font-serif);
  font-size: clamp(1.1rem, 2vw, 1.5rem);
  font-weight: 700;
  margin-bottom: .4rem;
}

.deal-subtitle { font-size: .82rem; color: var(--text-muted); margin-bottom: 1rem; }

.deal-cta {
  display: inline-flex; align-items: center; gap: .4rem;
  font-size: .82rem; font-weight: 600; color: var(--accent);
  transition: gap var(--transition);
}
.deal-card:hover .deal-cta { gap: .65rem; }

.countdown {
  display: flex; gap: .5rem; margin-bottom: 1rem;
}

.countdown-block {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: var(--radius-sm);
  padding: .4rem .6rem;
  text-align: center;
  min-width: 46px;
}
.countdown-num {
  font-size: 1.2rem; font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--text-primary);
  line-height: 1;
}
.countdown-label { font-size: .58rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: .05em; }

/* ===== EDITORIAL ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 1.5rem;
}

.editorial-main, .editorial-side { display: flex; flex-direction: column; gap: 1.5rem; }

.article-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  transition: border-color var(--transition), transform var(--transition);
}
.article-card:hover { border-color: rgba(232,184,109,.25); transform: translateY(-3px); }

.article-img {
  aspect-ratio: 16 / 7;
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem;
  background: linear-gradient(135deg, #1a1820 0%, #121018 100%);
  position: relative; overflow: hidden;
}

.article-img-sm {
  aspect-ratio: 16 / 9;
  font-size: 3rem;
}

.article-img-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.5) 0%, transparent 50%);
}

.article-body { padding: 1.4rem; }
.article-category {
  font-size: .68rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase;
  color: var(--accent); margin-bottom: .5rem;
}
.article-title {
  font-family: var(--font-serif);
  font-size: 1.1rem; font-weight: 700;
  line-height: 1.35;
  margin-bottom: .5rem;
}
.article-card.large .article-title { font-size: 1.4rem; }
.article-excerpt { font-size: .83rem; color: var(--text-secondary); line-height: 1.6; margin-bottom: 1rem; }
.article-meta { display: flex; align-items: center; gap: .75rem; font-size: .75rem; color: var(--text-muted); }
.article-meta-dot { width: 3px; height: 3px; border-radius: 50%; background: var(--text-muted); }

/* ===== BRANDS ===== */
.brands-strip {
  border-top: 1px solid var(--border);
  padding: 2.5rem 0;
}
.brands-label {
  text-align: center;
  font-size: .72rem; font-weight: 600; letter-spacing: .12em; text-transform: uppercase;
  color: var(--text-muted); margin-bottom: 1.75rem;
}
.brands-list {
  display: flex; align-items: center; justify-content: center;
  gap: 3rem; flex-wrap: wrap;
}
.brand-item {
  font-size: .95rem; font-weight: 700; letter-spacing: -.01em;
  color: var(--text-muted);
  transition: color var(--transition);
  cursor: pointer;
}
.brand-item:hover { color: var(--text-secondary); }

/* ===== NEWSLETTER ===== */
.newsletter-section { background: var(--bg-surface); }

.newsletter-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: clamp(2rem, 5vw, 3.5rem);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  position: relative; overflow: hidden;
}

.newsletter-box::before {
  content: '';
  position: absolute; top: -60px; right: -60px;
  width: 300px; height: 300px;
  background: radial-gradient(circle, rgba(232,184,109,.08) 0%, transparent 70%);
  pointer-events: none;
}

.newsletter-title {
  font-family: var(--font-serif);
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 700;
  margin-bottom: .75rem;
}
.newsletter-desc { font-size: .9rem; color: var(--text-secondary); line-height: 1.65; }

.newsletter-form { display: flex; flex-direction: column; gap: 1rem; }

.form-row { display: flex; gap: .75rem; }

.form-input {
  flex: 1;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: .75rem 1rem;
  color: var(--text-primary); font-size: .88rem; font-family: inherit;
  outline: none;
  transition: border-color var(--transition);
}
.form-input:focus { border-color: var(--accent-dim); }
.form-input::placeholder { color: var(--text-muted); }

.newsletter-form .btn-primary { padding: .75rem 1.6rem; border-radius: var(--radius-sm); white-space: nowrap; }

.form-note { font-size: .72rem; color: var(--text-muted); }
.form-note a { color: var(--text-secondary); text-decoration: underline; }

/* ===== FOOTER ===== */
footer {
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand-name {
  font-family: var(--font-serif);
  font-size: 1.3rem; font-weight: 700;
  margin-bottom: .65rem;
}
.footer-brand-name span { color: var(--accent); }
.footer-desc { font-size: .83rem; color: var(--text-muted); line-height: 1.7; max-width: 30ch; margin-bottom: 1.5rem; }

.social-links { display: flex; gap: .5rem; }
.social-btn {
  width: 36px; height: 36px;
  background: var(--bg-hover);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-muted); font-size: .85rem;
  transition: color var(--transition), border-color var(--transition);
  cursor: pointer;
}
.social-btn:hover { color: var(--accent); border-color: var(--accent-dim); }

.footer-col-title {
  font-size: .78rem; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: var(--text-secondary);
  margin-bottom: 1.1rem;
}

.footer-links { list-style: none; display: flex; flex-direction: column; gap: .55rem; }
.footer-links a { font-size: .84rem; color: var(--text-muted); transition: color var(--transition); }
.footer-links a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.75rem;
  display: flex; align-items: center; justify-content: space-between;
  gap: 1rem; flex-wrap: wrap;
}
.footer-copy { font-size: .78rem; color: var(--text-muted); }
.footer-legal { display: flex; gap: 1.5rem; }
.footer-legal a { font-size: .78rem; color: var(--text-muted); transition: color var(--transition); }
.footer-legal a:hover { color: var(--text-secondary); }

/* ===== TOAST ===== */
.toast-container {
  position: fixed; bottom: 2rem; right: 2rem; z-index: 999;
  display: flex; flex-direction: column; gap: .6rem;
  pointer-events: none;
}

.toast {
  display: flex; align-items: center; gap: .75rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: .85rem 1.2rem;
  box-shadow: 0 8px 32px rgba(0,0,0,.4);
  font-size: .84rem; font-weight: 500;
  pointer-events: auto;
  animation: slideInToast .25s ease;
  max-width: 320px;
}
.toast.removing { animation: slideOutToast .25s ease forwards; }
.toast-icon { font-size: 1.1rem; }
.toast-text strong { display: block; }
.toast-text span { font-size: .75rem; color: var(--text-muted); }

@keyframes slideInToast {
  from { opacity: 0; transform: translateX(20px) scale(.95); }
  to   { opacity: 1; transform: none; }
}
@keyframes slideOutToast {
  to { opacity: 0; transform: translateX(20px) scale(.95); }
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1100px) {
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 900px) {
  .nav-search { display: none; }
  .nav-links { display: none; }
  .hamburger { display: flex; }

  .hero-content { grid-template-columns: 1fr; }
  .hero-visual { display: none; }

  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deals-grid .deal-card:first-child { grid-column: 1 / -1; }

  .editorial-grid { grid-template-columns: 1fr; }

  .newsletter-box { grid-template-columns: 1fr; gap: 2rem; }

  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 640px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-stats { gap: 1.5rem; }
  .form-row { flex-direction: column; }
}

