*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:      #0d0d0f;
  --bg-surface:   #141417;
  --bg-card:      #1a1a1f;
  --bg-hover:     #22222a;
  --border:       #2a2a35;
  --accent:       #e8b86d;
  --accent-dim:   #c4954a;
  --accent-glow:  rgba(232,184,109,.18);
  --red:          #e85d5d;
  --text-primary: #f0eee8;
  --text-secondary:#9d9b94;
  --text-muted:   #5c5b56;
  --radius-sm:    6px;
  --radius-md:    12px;
  --radius-lg:    20px;
  --transition:   .22s ease;
  --font-sans:    'Inter', system-ui, -apple-system, sans-serif;
  --font-serif:   'Playfair Display', Georgia, serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; }
button { cursor: pointer; font-family: inherit; }

/* ===== TYPOGRAPHY ===== */
.section-label {
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
}

.section-header-text { display: flex; flex-direction: column; gap: .4rem; }

.view-all {
  font-size: .82rem;
  font-weight: 500;
  color: var(--accent);
  border-bottom: 1px solid var(--accent-dim);
  padding-bottom: 2px;
  white-space: nowrap;
  transition: color var(--transition), border-color var(--transition);
}
.view-all:hover { color: var(--text-primary); border-color: var(--text-secondary); }

/* ===== LAYOUT ===== */
.container { max-width: 1280px; margin: 0 auto; padding: 0 clamp(1rem, 4vw, 2.5rem); }
section { padding: 5rem 0; }
section + section { border-top: 1px solid var(--border); }

/* ===== NAVBAR ===== */
.navbar {
  position: sticky; top: 0; z-index: 100;
  background: rgba(13,13,15,.85);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border);
}

.navbar-inner {
  display: flex; align-items: center; gap: 1.5rem;
  height: 64px;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--text-primary);
  flex-shrink: 0;
}
.nav-logo span { color: var(--accent); }

.nav-links {
  display: flex; gap: .25rem; align-items: center;
  list-style: none; margin-left: 1.5rem;
}

.nav-links a {
  font-size: .85rem; font-weight: 500;
  color: var(--text-secondary);
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover { color: var(--text-primary); background: var(--bg-hover); }
.nav-links a.active { color: var(--text-primary); }

.nav-spacer { flex: 1; }

.nav-search {
  display: flex; align-items: center; gap: .6rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: .45rem 1rem;
  transition: border-color var(--transition);
}
.nav-search:focus-within { border-color: var(--accent-dim); }
.nav-search input {
  background: none; border: none; outline: none;
  color: var(--text-primary); font-size: .85rem;
  width: 180px;
}
.nav-search input::placeholder { color: var(--text-muted); }
.nav-search svg { flex-shrink: 0; color: var(--text-muted); }

.nav-actions { display: flex; gap: .5rem; align-items: center; }

.nav-btn {
  position: relative;
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  background: none; border: none;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.nav-btn:hover { color: var(--text-primary); background: var(--bg-hover); }

.badge {
  position: absolute; top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--accent); color: #000;
  font-size: .6rem; font-weight: 700;
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
}

.hamburger { display: none; }

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: min(90vh, 720px);
  display: flex; align-items: center;
  overflow: hidden;
  padding: 0;
  border-bottom: none;
}

.hero-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(232,184,109,.07) 0%, transparent 65%),
    radial-gradient(ellipse 50% 80% at 10% 80%, rgba(100,80,200,.06) 0%, transparent 60%),
    linear-gradient(160deg, #0f0f14 0%, #0d0d0f 100%);
}

.hero-grid-overlay {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: .25;
  mask-image: radial-gradient(ellipse 70% 70% at 60% 50%, black 30%, transparent 75%);
}

.hero-content {
  position: relative; z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  padding: 5rem 0;
}

.hero-eyebrow {
  display: inline-flex; align-items: center; gap: .5rem;
  background: var(--accent-glow);
  border: 1px solid rgba(232,184,109,.25);
  border-radius: 999px;
  padding: .3rem .9rem;
  font-size: .72rem; font-weight: 600; letter-spacing: .1em;
  text-transform: uppercase; color: var(--accent);
  margin-bottom: 1.4rem;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.02em;
  margin-bottom: 1.2rem;
}

.hero-title .highlight {
  background: linear-gradient(135deg, var(--accent) 0%, #f0d080 60%, var(--accent-dim) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-desc {
  font-size: 1.05rem;
  color: var(--text-secondary);
  max-width: 42ch;
  margin-bottom: 2.2rem;
  line-height: 1.75;
}

.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; align-items: center; }

.btn-primary {
  display: inline-flex; align-items: center; gap: .55rem;
  background: var(--accent);
  color: #0d0d0f;
  font-size: .9rem; font-weight: 700;
  padding: .8rem 1.8rem;
  border: none; border-radius: 999px;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 4px 20px var(--accent-glow);
}
.btn-primary:hover { background: #f0c87a; transform: translateY(-2px); box-shadow: 0 8px 28px rgba(232,184,109,.3); }

.btn-ghost {
  display: inline-flex; align-items: center; gap: .55rem;
  background: none;
  color: var(--text-secondary);
  font-size: .9rem; font-weight: 500;
  padding: .8rem 1.4rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.btn-ghost:hover { color: var(--text-primary); border-color: var(--text-secondary); background: var(--bg-hover); }

.hero-stats {
  display: flex; gap: 2.5rem; margin-top: 3rem;
}

.hero-stat-num {
  font-size: 1.5rem; font-weight: 800;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}
.hero-stat-label { font-size: .78rem; color: var(--text-muted); margin-top: .1rem; }

.hero-visual {
  position: relative;
  display: flex; justify-content: center; align-items: center;
}

.hero-product-card {
  position: relative;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  width: 340px;
  box-shadow: 0 24px 80px rgba(0,0,0,.5);
}

.hero-product-card::before {
  content: '';
  position: absolute; inset: -1px;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, rgba(232,184,109,.2), transparent 60%);
  z-index: -1;
}

.hero-img-wrap {
  border-radius: var(--radius-md);
  overflow: hidden;
  aspect-ratio: 1 / 1;
  background: linear-gradient(135deg, #1e1e26 0%, #16161d 100%);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 1.4rem;
  font-size: 6rem;
}

.hero-product-tag {
  position: absolute; top: 1.2rem; right: 1.2rem;
  background: var(--red);
  color: #fff;
  font-size: .7rem; font-weight: 700;
  padding: .25rem .65rem; border-radius: 999px;
  letter-spacing: .06em; text-transform: uppercase;
}

.hero-product-name {
  font-weight: 600; font-size: 1rem; margin-bottom: .25rem;
}
.hero-product-brand { font-size: .8rem; color: var(--text-muted); margin-bottom: .75rem; }

.hero-product-footer {
  display: flex; align-items: center; justify-content: space-between;
}
.hero-product-price { font-size: 1.2rem; font-weight: 700; color: var(--accent); }
.hero-product-old { font-size: .82rem; color: var(--text-muted); text-decoration: line-through; margin-left: .4rem; }

.hero-add-btn {
  display: flex; align-items: center; gap: .4rem;
  background: var(--accent); color: #0d0d0f;
  font-size: .8rem; font-weight: 700;
  padding: .55rem 1rem; border: none; border-radius: 999px;
  transition: background var(--transition);
}
.hero-add-btn:hover { background: #f0c87a; }

.floating-badge {
  position: absolute;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: .75rem 1rem;
