    const wishlisted = wishlist.has(p.id);
    return `
      <div class="product-card" data-id="${p.id}">
        <div class="product-img-wrap">
          <span>${p.emoji}</span>
          <span class="product-tag ${tagClasses[p.tag]}">${tagLabels[p.tag]}</span>
          <div class="product-actions">
            <button class="product-action-btn wishlist-btn ${wishlisted ? 'wishlisted' : ''}"
              data-id="${p.id}" title="${wishlisted ? 'Remove from wishlist' : 'Add to wishlist'}">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="${wishlisted ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2">
