function initNewsletter() {
  const form = document.getElementById('newsletter-form');
  form?.addEventListener('submit', e => {
    e.preventDefault();
    const input = form.querySelector('input[type="email"]');
    if (input.value) {
      showToast('✉️', 'You\'re subscribed!', 'Welcome to the inner circle.');
      input.value = '';
    }
  });
}

// ===== SEARCH =====
function initSearch() {
  const input = document.getElementById('search-input');
  input?.addEventListener('keydown', e => {
    if (e.key === 'Enter' && input.value.trim()) {
      showToast('🔍', 'Searching…', `"${input.value.trim()}"`);
      input.value = '';
    }
  });
}

// ===== HERO ADD =====
function initHeroAdd() {
  document.getElementById('hero-add')?.addEventListener('click', () => {
    const btn = document.getElementById('hero-add');
    addToCart(1, btn);
  });
}

// ===== MOBILE MENU =====
function initMobileMenu() {
  const hamburger = document.querySelector('.hamburger');
  const navLinks = document.querySelector('.nav-links');
  hamburger?.addEventListener('click', () => {
    const open = navLinks.style.display === 'flex';
    navLinks.style.display = open ? '' : 'flex';
    navLinks.style.flexDirection = 'column';
    navLinks.style.position = 'absolute';
    navLinks.style.top = '64px';
    navLinks.style.left = '0';
    navLinks.style.right = '0';
    navLinks.style.background = 'var(--bg-surface)';
    navLinks.style.borderBottom = '1px solid var(--border)';
    navLinks.style.padding = '1rem';
    if (open) navLinks.style.display = 'none';
  });
}

// ===== INIT =====
document.addEventListener('DOMContentLoaded', () => {
  renderProducts();
  setCountdown();
  initNewsletter();
  initSearch();
  initHeroAdd();
  initMobileMenu();
  updateCartBadge();
});
