+                <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
+              </svg>
+            </button>
+            <button class="product-action-btn" title="Quick view">
+              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
+                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>
+              </svg>
+            </button>
+          </div>
+        </div>
+        <div class="product-info">
+          <div class="product-brand">${p.brand}</div>
+          <div class="product-name">${p.name}</div>
+          <div class="product-rating">
+            <span class="stars">${stars(p.rating)}</span>
+            <span class="rating-count">${p.rating} (${p.reviews.toLocaleString()})</span>
+          </div>
+          <div class="product-footer">
+            <div class="price-group">
+              <span class="price">${formatPrice(p.price)}</span>
+              ${p.oldPrice ? `<span class="price-old">${formatPrice(p.oldPrice)}</span>` : ''}
+              ${save ? `<span class="price-save">${save}</span>` : ''}
+            </div>
+            <button class="add-to-cart" data-id="${p.id}" title="Add to cart">
+              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
+                <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/>
+                <path d="M16 10a4 4 0 0 1-8 0"/>
+              </svg>
+            </button>
+          </div>
+        </div>
+      </div>`;
+  }).join('');
+
+  // Bind events
+  grid.querySelectorAll('.add-to-cart').forEach(btn => {
+    btn.addEventListener('click', e => {
+      e.stopPropagation();
+      const id = +btn.dataset.id;
+      addToCart(id, btn);
+    });
+  });
+
+  grid.querySelectorAll('.wishlist-btn').forEach(btn => {
+    btn.addEventListener('click', e => {
+      e.stopPropagation();
+      toggleWishlist(+btn.dataset.id);
+    });
+  });
+}
+
+// ===== CART =====
+function addToCart(id, btn) {
+  const product = products.find(p => p.id === id);
+  const existing = cart.find(i => i.id === id);
+  if (existing) existing.qty++;
+  else cart.push({ ...product, qty: 1 });
+
+  updateCartBadge();
+  animateCartBtn(btn);
+  showToast('🛒', 'Added to cart', product.name);
+}
+
+function updateCartBadge() {
+  const total = cart.reduce((s, i) => s + i.qty, 0);
+  document.getElementById('cart-badge').textContent = total;
+  document.getElementById('cart-badge').style.display = total > 0 ? 'flex' : 'none';
+}
+
+function animateCartBtn(btn) {
+  btn.classList.add('added');
+  btn.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>`;
+  setTimeout(() => {
+    btn.classList.remove('added');
+    btn.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>`;
+  }, 1500);
+}
+
+// ===== WISHLIST =====
+function toggleWishlist(id) {
+  const product = products.find(p => p.id === id);
+  if (wishlist.has(id)) {
+    wishlist.delete(id);
+    showToast('💔', 'Removed from wishlist', product.name);
+  } else {
+    wishlist.add(id);
+    showToast('❤️', 'Saved to wishlist', product.name);
+  }
+  renderProducts();
+}
+
+// ===== TOAST =====
+function showToast(icon, title, subtitle) {
+  const container = document.getElementById('toast-container');
+  const el = document.createElement('div');
+  el.className = 'toast';
+  el.innerHTML = `
+    <span class="toast-icon">${icon}</span>
+    <div class="toast-text">
+      <strong>${title}</strong>
+      <span>${subtitle}</span>
+    </div>`;
+  container.appendChild(el);
+  setTimeout(() => {
+    el.classList.add('removing');
+    el.addEventListener('animationend', () => el.remove());
+  }, 3000);
+}
+
+// ===== COUNTDOWN =====
+function setCountdown() {
+  // Target: 8 hours from now
+  const target = new Date(Date.now() + 8 * 60 * 60 * 1000 + 23 * 60 * 1000 + 47 * 1000);
+
+  function update() {
+    const diff = target - Date.now();
+    if (diff <= 0) { clearInterval(timer); return; }
+    const h = Math.floor(diff / 3600000);
+    const m = Math.floor((diff % 3600000) / 60000);
+    const s = Math.floor((diff % 60000) / 1000);
+    const pad = n => String(n).padStart(2, '0');
+    const el = document.getElementById('countdown');
+    if (el) el.innerHTML = `
+      <div class="countdown-block"><div class="countdown-num">${pad(h)}</div><div class="countdown-label">hrs</div></div>
+      <div class="countdown-block"><div class="countdown-num">${pad(m)}</div><div class="countdown-label">min</div></div>
+      <div class="countdown-block"><div class="countdown-num">${pad(s)}</div><div class="countdown-label">sec</div></div>`;
+  }
+  update();
+  const timer = setInterval(update, 1000);
+}
+
+// ===== NEWSLETTER =====
+function initNewsletter() {
+  const form = document.getElementById('newsletter-form');
+  form?.addEventListener('submit', e => {
+    e.preventDefault();
+    const input = form.querySelector('input[type="email"]');
+    if (input.value) {
+      showToast('✉️', 'You\'re subscribed!', 'Welcome to the inner circle.');
+      input.value = '';
+    }
+  });
+}
+
+// ===== SEARCH =====
+function initSearch() {
+  const input = document.getElementById('search-input');
+  input?.addEventListener('keydown', e => {
+    if (e.key === 'Enter' && input.value.trim()) {
+      showToast('🔍', 'Searching…', `"${input.value.trim()}"`);
+      input.value = '';
+    }
+  });
+}
+
+// ===== HERO ADD =====
+function initHeroAdd() {
+  document.getElementById('hero-add')?.addEventListener('click', () => {
+    const btn = document.getElementById('hero-add');
+    addToCart(1, btn);
+  });
+}
+
+// ===== MOBILE MENU =====
+function initMobileMenu() {
+  const hamburger = document.querySelector('.hamburger');
+  const navLinks = document.querySelector('.nav-links');
+  hamburger?.addEventListener('click', () => {
+    const open = navLinks.style.display === 'flex';
+    navLinks.style.display = open ? '' : 'flex';
+    navLinks.style.flexDirection = 'column';
+    navLinks.style.position = 'absolute';
+    navLinks.style.top = '64px';
+    navLinks.style.left = '0';
+    navLinks.style.right = '0';
+    navLinks.style.background = 'var(--bg-surface)';
+    navLinks.style.borderBottom = '1px solid var(--border)';
+    navLinks.style.padding = '1rem';
+    if (open) navLinks.style.display = 'none';
+  });
+}
+
+// ===== INIT =====
+document.addEventListener('DOMContentLoaded', () => {
+  renderProducts();
+  setCountdown();
+  initNewsletter();
+  initSearch();
+  initHeroAdd();
+  initMobileMenu();
+  updateCartBadge();
+});
+
')

